<script setup lang="ts">
import {ArrowRight,Play,Plus,Search,MessageSquare,Download,MapPin} from 'lucide-vue-next'
import {pagePositionContent,thumbnailPlaceholder} from '~/shared/cms/workbench.mjs'
const props=defineProps<{block:any;bodies:Record<string,any>;selected?:any;pageTitle:string;presentation?:any;focusedField?:string}>()
const scene=computed(()=>pagePositionContent(props.block,props.bodies,props.presentation,props.selected,props.focusedField))
const nearby=computed(()=>scene.value.sections.filter((_:any,i:number)=>Math.abs(i-(props.block?.positionIndex||1)+1)<=1))
const illustration=computed(()=>thumbnailPlaceholder(props.block?.name||''))
const highlighted=(path:string)=>props.focusedField===path
const headings=computed(()=>scene.value.heading.filter((f:any)=>!/英文|小標|語音/.test(f.label)))
const eyebrows=computed(()=>scene.value.heading.filter((f:any)=>/英文|小標/.test(f.label)))
const regions=computed(()=>Object.entries(props.bodies['data-storeCases']?.regionCities||{}) as [string,string[]][])
const captions=computed(()=>scene.value.bodyText.filter((f:any)=>!/供語音|載入|失敗|格式欄位|頁數欄位|大小欄位/.test(f.label)))
const media=computed(()=>scene.value.media.filter((f:any,index:number)=>index<3||highlighted(f.path)))
const itemText=(item:any)=>{const text=item.value?.summary?.excerpt||item.value?.intro?.paragraphs||item.value?.description||item.value?.paragraphs||item.value?.detail||item.value?.quote||item.value?.excerpt||item.value?.summary||'';return Array.isArray(text)?text.join('\n'):typeof text==='string'?text:''}
const formFields=computed(()=>props.block?.id.startsWith('franchise-form:')?['聯絡姓名','電子郵件','聯絡電話','希望開店地區']:['聯絡人','聯絡電話','建設公司','建案資訊'])
const links=computed(()=>scene.value.items.flatMap((i:any)=>i.value?.children||i.value?.links||[i.value]).filter((i:any)=>i?.label||i?.title).slice(0,8))
const table=computed(()=>{const f=props.block?.fields.find((f:any)=>f.path==='systemCabinetMaterials');return f?props.bodies[f.documentId]?.[f.path]:null})
</script>
<template>
 <div class="cms-page-position-scene cms-website-scene" :data-position-kind="scene.kind">
  <div class="cms-position-sitebar"><span>設計案例 · 廚房產品 · 門市與服務</span><img src="/home-2026/logos/sakura-kitchen-horizontal.svg" alt="SAKURA KITCHEN" /><span>品牌承諾 · 我要加盟</span></div>
  <div v-if="scene.contextImage&&scene.kind!=='hero'" class="cms-scene-context-image"><AdminThumbnail :src="scene.contextImage" :alt="pageTitle+'頁面位置參照'" /><span>{{ pageTitle }}</span></div>
  <ol v-if="nearby.length" class="cms-scene-locations" aria-label="此區塊在官網的順序"><li v-for="part in nearby" :key="part.name" :class="{'is-current':part.name===block?.name}">{{ part.name===block?.name?'正在修改：':'' }}{{ part.name }}</li></ol>
  <section class="cms-scene-target" :aria-label="block?.name+'的位置示意'">
   <span class="cms-scene-tag">正在修改：{{ selected?.caption||block?.name }}</span>
   <template v-if="scene.kind==='hero'">
    <div class="cms-scene-hero"><AdminThumbnail :src="scene.image||scene.contextImage||illustration" :alt="block?.name+'主圖片位置'" /><div class="cms-scene-hero-copy"><span v-for="f in eyebrows" :key="f.path" :class="{'is-focused':highlighted(f.path)}">{{ f.value }}</span><h3 v-for="f in headings" :key="f.path" :class="{'is-focused':highlighted(f.path)}">{{ f.value }}</h3><h3 v-if="!headings.length">{{ scene.title }}</h3><p v-for="f in captions.slice(0,2)" :key="f.path" :class="{'is-focused':highlighted(f.path)}">{{ f.value }}</p></div></div>
   </template>
   <template v-else>
    <header v-if="headings.length||eyebrows.length" class="cms-scene-heading"><small v-for="f in eyebrows" :key="f.path" :class="{'is-focused':highlighted(f.path)}">{{ f.value }}</small><h3 v-for="f in headings" :key="f.path" :class="{'is-focused':highlighted(f.path)}">{{ f.value }}</h3></header>
    <template v-if="scene.kind==='filter'"><div class="cms-scene-filter"><strong :class="{'is-focused':highlighted('copy.text3')}">{{ bodies['view-pages-gallery-index']?.copy?.text3 }}</strong><span :class="{'is-focused':highlighted('copy.text4')}">{{ bodies['view-pages-gallery-index']?.copy?.text4 }}</span><span v-for="[region] in regions" :key="region">{{ region }}</span></div><div class="cms-scene-filter"><strong :class="{'is-focused':highlighted('copy.text5')}">{{ bodies['view-pages-gallery-index']?.copy?.text5 }}</strong><span v-for="city in regions[0]?.[1]?.slice(0,3)||[]" :key="city">{{ city }}</span></div><AdminThumbnail :src="presentation?.specialImage||illustration" :alt="block?.name+'下方的門市清單位置'" class="cms-scene-wide-image" /></template>
    <template v-else-if="scene.kind==='results'"><AdminThumbnail :src="presentation?.specialImage||illustration" :alt="pageTitle+'搜尋結果的位置參照'" class="cms-scene-wide-image" /><p v-for="f in scene.text" :key="f.path" class="cms-scene-result" :class="{'is-focused':highlighted(f.path)}"><Search :size="18" />{{ bodies['data-storeCases']?.storeCases?.length||0 }} {{ f.value }}</p><small class="cms-scene-a11y">這段說明供語音朗讀使用。</small></template>
    <template v-else-if="scene.kind==='empty'"><AdminThumbnail :src="illustration" :alt="block?.name+'出現位置示意圖'" class="cms-scene-small-image" /><div class="cms-scene-empty"><Search :size="25" /><p v-for="f in captions" :key="f.path" :class="{'is-focused':highlighted(f.path)}">{{ f.value }}</p></div></template>
    <template v-else-if="scene.kind==='navigation'||scene.kind==='footer'"><div class="cms-scene-navigation" :class="{'is-footer':scene.kind==='footer'}"><AdminThumbnail :src="scene.image||illustration" :alt="block?.name+'導覽位置圖'" contain /><h3 v-if="selected">{{ selected.caption }}</h3><div class="cms-scene-link-grid"><span v-for="(link,index) in links" :key="index">{{ link.label||link.title }}<ArrowRight :size="12" /></span></div><p v-for="f in captions" :key="f.path" :class="{'is-focused':highlighted(f.path)}">{{ f.value }}</p></div></template>
    <template v-else-if="scene.kind==='faq'"><AdminThumbnail :src="scene.image||illustration" :alt="block?.name+'問答位置圖'" class="cms-scene-small-image" /><h3 v-if="selected" class="cms-scene-item-title">{{ selected.caption }}</h3><div v-for="(item,index) in scene.questions" :key="index" class="cms-scene-question"><strong>{{ item.question||item.title||item.label }}</strong><Plus :size="15" /><p v-if="index===0">{{ item.answer||item.intro }}</p></div></template>
    <template v-else-if="scene.kind==='form'"><AdminThumbnail :src="scene.image||scene.contextImage||illustration" :alt="block?.name+'表單與聯絡資訊位置圖'" class="cms-scene-wide-image" /><p v-for="f in captions" :key="f.path" :class="{'is-focused':highlighted(f.path)}">{{ f.value }}</p><div class="cms-scene-form-fields" aria-label="官網表單填寫位置示意"><span v-for="name in formFields" :key="name">{{ name }}<i /></span></div></template>
    <template v-else-if="scene.kind==='map'||scene.kind==='stores'"><AdminThumbnail :src="scene.image||illustration" :alt="block?.name+'門市位置圖'" class="cms-scene-wide-image" :contain="!scene.image" /><h3 class="cms-scene-item-title">{{ selected?.value?.storeName||selected?.caption||scene.title }}</h3><p v-if="selected?.value?.address"><MapPin :size="15" aria-hidden="true" />{{ selected.value.address }}</p><p v-if="selected?.value?.hours">{{ selected.value.hours }}</p><p v-if="selected?.value?.contact?.phone||selected?.value?.phone">{{ selected.value.contact?.phone||selected.value.phone }}</p><dl v-if="scene.kind==='map'&&regions.length" class="cms-scene-details"><template v-for="[region,cities] in regions" :key="region"><dt>{{ region }}</dt><dd>{{ cities.join('、') }}</dd></template></dl><dl v-if="scene.details.length" class="cms-scene-details"><template v-for="f in scene.details" :key="f.label"><dt>{{ f.label }}</dt><dd>{{ f.value }}</dd></template></dl></template>
    <template v-else-if="scene.kind==='video'"><div class="cms-scene-video"><AdminThumbnail :src="scene.image||illustration" :alt="block?.name+'影片封面位置'" /><Play :size="32" aria-hidden="true" /></div><h3 v-if="selected" class="cms-scene-item-title">{{ selected.caption }}</h3><p v-if="scene.description">{{ scene.description }}</p></template>
    <template v-else-if="scene.kind==='table'"><AdminThumbnail :src="illustration" :alt="block?.name+'比較表位置示意圖'" class="cms-scene-small-image" /><div v-if="table" class="cms-scene-table-wrap"><table><thead><tr><th :class="{'is-focused':highlighted('copy.text6')}">{{ bodies['view-pages-knowledge-design-systemcabinet']?.copy?.text6||'材質' }}</th><th v-for="(column,index) in table.columns" :key="index">{{ typeof column==='string'?column:column.label }}</th></tr></thead><tbody><tr v-for="(row,index) in table.rows.slice(0,3)" :key="index"><th scope="row">{{ row.label }}</th><td v-for="(cell,i) in row.values" :key="i">{{ cell }}</td></tr></tbody></table></div><p v-for="f in captions" :key="f.path" :class="{'is-focused':highlighted(f.path)}">{{ f.value }}</p></template>
    <template v-else-if="scene.kind==='comments'"><AdminThumbnail :src="illustration" :alt="block?.name+'留言位置示意圖'" class="cms-scene-small-image" /><p v-for="f in captions" :key="f.path" :class="{'is-focused':highlighted(f.path)}"><MessageSquare :size="18" aria-hidden="true" />{{ f.value }}</p><div class="cms-scene-form-fields"><span>留言內容<i class="is-long" /></span></div></template>
    <template v-else-if="scene.kind==='download'"><AdminThumbnail :src="illustration" :alt="block?.name+'檔案預覽位置示意圖'" class="cms-scene-small-image" /><div class="cms-scene-download"><Download :size="28" /><p v-for="f in scene.text" :key="f.path" :class="{'is-focused':highlighted(f.path)}">{{ f.value }}</p></div></template>
    <template v-else-if="scene.items.length"><div class="cms-scene-cards" :class="{'is-single':scene.items.length===1,'is-logo':scene.kind==='logos','is-catalogue':scene.kind==='catalogue','is-timeline':scene.kind==='timeline','is-step':scene.kind==='steps'}"><article v-for="(item,index) in scene.items" :key="index"><AdminThumbnail :src="item.image||scene.image||illustration" :alt="item.title+'對應圖片'" :contain="['logos','products','steps'].includes(scene.kind)" /><small v-if="item.value?.number||item.value?.englishTitle||item.value?.eyebrow">{{ item.value.number||item.value.englishTitle||item.value.eyebrow }}</small><h3>{{ item.title }}</h3><p v-if="itemText(item)">{{ itemText(item) }}</p><p v-if="item.value?.enabled===false" class="cms-scene-paused">此內容目前暫停顯示</p></article></div></template>
    <template v-else><div v-if="media.length>1" class="cms-scene-media-grid"><figure v-for="f in media" :key="f.path" :class="{'is-focused':highlighted(f.path)}"><AdminThumbnail :src="f.image" :alt="f.label+'對應圖片'" /><figcaption>{{ f.label }}</figcaption></figure></div><AdminThumbnail v-else :src="scene.image||illustration" :alt="block?.name+(scene.image?'對應圖片':'位置示意圖')" class="cms-scene-wide-image" :contain="!scene.image||scene.kind==='logos'" /><dl v-if="scene.details.length" class="cms-scene-details"><template v-for="f in scene.details" :key="f.label"><dt>{{ f.label }}</dt><dd>{{ f.value }}</dd></template></dl></template>
    <div v-if="!['filter','results','empty','navigation','footer','form','table','comments','download'].includes(scene.kind)" class="cms-scene-reading"><p v-for="f in captions" :key="f.path" :class="{'is-focused':highlighted(f.path)}">{{ f.value }}</p></div>
   </template>
   <div v-if="scene.buttons.length" class="cms-scene-buttons"><span v-for="field in scene.buttons" :key="field.path" :class="{'is-focused':highlighted(field.path)}">{{ field.value }}<ArrowRight :size="13" /></span></div>
  </section>
  <div class="cms-scene-footer">{{ pageTitle }} · 頁尾</div>
 </div>
</template>
